    // 解析 "自得奇功·后天内功《汉宫秋》、自得奇功·后天掌法《桃花扇》、..." 或 "后天刀法《飞天御剑流》、..."
    var customs = [];
    skillStr.split('、').forEach(function(part) {
      part = part.trim().replace(/^自得奇功[··]?\s*/, '');
      var m = part.match(/^(.+?)《([^》]+)》$/);
      if (m) {
        var gradeType = m[1].trim();
        var gm = gradeType.match(/^(不入流|三品|二品|一品|后天|先天)(.+)$/);
        var sname = m[2].trim();
        customs.push({
          name: sname,
          grade: gm ? gm[1] : '三品',
          type: gm ? gm[2] : '内功',
          desc: PRESET_DESCS[sname] || ''
        });
      }
    });
    if (customs.length) fillCustomSkills(customs);
  } else {
    // 宗门传承：切换到下拉栏，解析武学并选中
    document.getElementById('skill-type').value = 'auto';
    updateSkillInput();
    var skills = skillStr.split('、').map(function(s) { return s.trim(); }).filter(function(s) { return s; });
    var s1 = document.getElementById('skill-1');
    var s2 = document.getElementById('skill-2');
    var s3 = document.getElementById('skill-3');
    if (s1 && skills[0]) { refreshSelects(); s1.value = skills[0]; }
    if (s2 && skills[1]) { refreshSelects(); s2.value = skills[1]; }
    if (s3 && skills[2]) { refreshSelects(); s3.value = skills[2]; }
    refreshSelects();
    updateSkillValue();
  }

  // Preset proficiency strings must survive the same native cap as restored slots.
  同步自得熟练度();刷新武学熟练度();
  const presetProfs=Array.isArray(p.profs)?p.profs:String(p.profs||'').split('、');
  const presetRows=document.querySelectorAll('#custom-skills .custom-skill-row');
  presetProfs.forEach((value,i)=>{const el=isCustom?presetRows[i]?.querySelector('.cs-prof'):document.getElementById('prof-'+(i+1));if(el&&Array.from(el.options).some(op=>op.value===value&&!op.disabled))el.value=value;});
  // 高亮提示玩家填写
  ['n','age','nick','look'].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) { el.style.borderColor = '#a81c1c'; el.placeholder = '← 请填写'; }
  });
}

