}

/* ═══════════ [v3.1] 武学熟练度（口径：《世界观/武学熟练度》） ═══════════ */
const 熟练度表 = [
  { 名: '皮毛', 述: '初识门径；使用本档已定义的招式与词条' },
  { 名: '粗通', 述: '招式渐熟；开放本档已定义的招式与词条' },
  { 名: '登堂', 述: '掌握要领；开放本档已定义的招式与词条' },
  { 名: '入室', 述: '技艺深入；开放本档已定义的招式与词条' },

  { 名: '圆满', 述: '本门造诣圆熟；蓄势、破绽与伤害仍按具体招式和词条结算' },
];
/** 境界锁死上限：低境界强行修炼高品武学，熟练度受生理极限锁死（《武学熟练度》境界锁死机制） */
const DLH_OPENING_MASTERY=(function(){const grades=['不入流','三品','二品','一品','后天','先天'];
  function level(s){s=String(s||'');if(/^[六七八]关气海/.test(s))return 6;const m=s.match(/^([一二三四五六七八九])境/);return m?'一二三四五六七八九'.indexOf(m[1])+1:0;}
  function limit(realm,grade){const n=level(realm),g=grades.indexOf(grade);if(!n||g<0)return -1;if(n>=8)return 4;if(n===7)return g===5?3:4;if(n===6)return g===5?2:4;
    const rows={1:[4,1,0,0,0,0],2:[4,2,1,0,0,0],3:[4,4,2,0,0,0],4:[4,4,4,2,1,0],5:[4,4,4,4,2,1]};const cap=rows[n][g];return n===5&&g===4&&/_[七八]关/.test(realm)?3:cap;}

return {level,limit};})();
function 熟练度上限(lvl,grade){if(lvl==='无修为')return grade==='不入流'?'圆满':'不可';const cap=DLH_OPENING_MASTERY.limit(lvl,grade);return cap<0?'不可':['皮毛','粗通','登堂','入室','圆满'][cap];}

/** 按境界与品级重填一个熟练度下拉；超上限的档位置灰不可选 */
function 填熟练度(sel, lvl, grade, 保留) {
  if (!sel) return '';
  const 上限 = 熟练度上限(lvl, grade);
  const 上限序 = 熟练度表.findIndex(function (x) { return x.名 === 上限; });
  const 想选 = 保留 || sel.value || '皮毛';
  sel.innerHTML = '';
  let 选中 = false;
  熟练度表.forEach(function (p, i) {
    const op = document.createElement('option');
    const 锁 = (上限 === '不可') || (上限序 >= 0 && i > 上限序);   /* ★ 不可 ⇒ 整条全灰 ✓（原写法会误判为『没限制』✗）*/
    op.value = p.名;
    op.textContent = p.名 + (锁 ? '·锁死' : '');
    op.title = p.述 + (锁 ? '　【已达本境界上限，需先提升境界】' : '');

    if (锁) op.disabled = true;
    if (p.名 === 想选 && !锁) { op.selected = true; 选中 = true; }
    sel.appendChild(op);
  });
  if (!选中) sel.value = (上限 === '不可') ? '皮毛' : 上限;   /* 不可时兜底停在皮毛 ✓ 不写非法值 ✓ */
  return 上限;
}
function 刷新武学熟练度() {
  try {
    const lvl = document.getElementById('level') ? document.getElementById('level').value : '';
    [1, 2, 3].forEach(function (i) {
      const sk = document.getElementById('skill-' + i);
      const pf = document.getElementById('prof-' + i);
      if (!sk || !pf) return;
      const 上限 = 填熟练度(pf, lvl, gradeOf(sk.value || ''), pf.value);
      const note = document.getElementById('prof-note-' + i);
      if (note) {
        const 当前 = 熟练度表.find(function (x) { return x.名 === pf.value; }) || {};
        note.textContent = sk.value
          ? ''
          : '';
      }
    });
    const box = document.getElementById('custom-skills');
    if (box) box.querySelectorAll('.custom-skill-row').forEach(function (r) {
      const pf = r.querySelector('.cs-prof'), g = r.querySelector('.cs-grade');
      if (pf) 填熟练度(pf, lvl, g ? g.value : '', pf.value);
    });
  } catch (e) { console.error('熟练度刷新失败', e); }
}
/** 自得武学行的熟练度下拉：缺则补，有则【按当前品级重算】锁死上限
    —— AI 生成（fillCustomSkills）与启卷（applyDataToForm）都是程序化赋品级，不触发 change，故必须每次全量重算 */
function 预设品级(name){const p=PRESETS[document.getElementById('preset')?.value];if(!p||DLH_OPENING_MASTERY.level(document.getElementById('level')?.value)<DLH_OPENING_MASTERY.level(p.level))return '';const part=String(p.skill||'').split('、').find(part=>part.includes('《'+name+'》'));return /(?:^|·)(三品|二品|一品|后天|先天)/.exec(part||'')?.[1]||'';}
function 预设先天(name){return 预设品级(name)==='先天';}
function 同步自得熟练度() {
  if (同步自得熟练度._忙) return;
  同步自得熟练度._忙 = true;
  try {
    const lvl = document.getElementById('level') ? document.getElementById('level').value : '';
    document.querySelectorAll('#custom-skills .custom-skill-row').forEach(function (r) {
      const line = r.querySelector('.cs-line');
      if (!line) return;
      let pf = r.querySelector('.cs-prof');
      if (!pf) {
        pf = document.createElement('select');
        pf.className = 'cs-prof';
        pf.title = '熟练度（《世界观/武学熟练度》）';
        line.insertBefore(pf, r.querySelector('.cs-remove') || null);
        pf.value = '皮毛';
      }
      const g = r.querySelector('.cs-grade');
      /* ★ 品级纠错 ✓：境界一变，已有行的品级也要按新境界重滤（学不来的置灰并回退到不入流 ✗）*/
      if (g) {
        const old=g.value,预设档=预设品级(r.querySelector('.cs-name')?.value),先天例外=预设档==='先天',可品=[...new Set(['不入流'].concat(allowedGradesFor(lvl),预设档?[预设档]:[]))];
        g.replaceChildren(...可品.map(v=>{const op=document.createElement('option');op.value=v;op.textContent=v;if(v==='先天')op.className='opt-xian';op.disabled=v==='先天'&&!先天例外;return op;}));
        g.value=可品.includes(old)?old:'不入流';
        if(g.value!==old)pf.value='皮毛';
      }
      const 上限 = 填熟练度(pf, lvl, g ? g.value : '', pf.value);
      // 同步一行可见提示（与宗门传承一致的"系数 + 描述 + 上限"），让锁死一眼可见
      let note = r.querySelector('.cs-prof-note');
      if (!note) {
        note = document.createElement('div');
        note.className = 'cs-prof-note prof-note';
        line.parentNode.insertBefore(note, line.nextSibling);
      }
      const 当前 = 熟练度表.find(function (x) { return x.名 === pf.value; }) || {};
      note.textContent = '';
  /* __解锁先天：来自预设且品级为【先天】的行，解除"先天"选项禁用并选中；其余行保持禁用（点不出来） */
  if (g && g.value === '先天'&&预设先天(r.querySelector('.cs-name')?.value)) { var __o = g.querySelector('option[value="先天"]'); if (__o) { __o.disabled = false; g.value = '先天'; } }
    });
  } catch (e) { console.error('自得武学熟练度同步失败', e); }
  同步自得熟练度._忙 = false;
}

