    if(g===预设品级(s.name)&&!Array.from(row.querySelector('.cs-grade').options).some(op=>op.value===g)){const op=document.createElement('option');op.value=g;op.textContent=g;if(g==='先天')op.className='opt-xian';row.querySelector('.cs-grade').appendChild(op);}
