    const st = document.getElementById('slot-' + i + '-status');
    const lb = document.getElementById('load-btn-' + i);
    const cb = document.getElementById('clear-btn-' + i);
    if (saved) {
      try { const dd = JSON.parse(saved); if (st) { st.innerText = dd.n || '无名氏'; st.style.color = '#8b7355'; } }
      catch (e) { if (st) { st.innerText = '数据损坏'; st.style.color = '#b71c1c'; } }
