function 档案文本(){
  const d = id => document.getElementById(id).value.trim();
  const info = {
    n: d('n') || '无名氏',
    g: document.getElementById('g').value,
    age: d('age') || '未知',
    nick: d('nick') || '无',
    level: document.getElementById('level').value,
    faction: document.getElementById('faction').value.replace(/^[\u4e00-\u9fff]{1,4}州\s*[-—]\s*/,''),
    look: d('look') || '平平无奇',
    loc: (document.getElementById('loc').value.split(' — ')[0] || document.getElementById('loc').value).trim(),
    job: d('job') || '江湖散客',
    bg: d('bg') || '来历不详',
    party:d('opening-party'),talents:d('opening-talents'),
    money: d('asset-money') || '身无长物',
    gear: d('asset-gear') || '两手空空',
    scene: d('scene') || '茫然立于天地之间',
    whyNoRealm: d('why-norealm') || ''
  };
  if (info.faction === '无名小派') {
    const mn = d('mini-name') || '无名小派';
    const md = d('mini-desc') || '';
    info.faction = '无名小派·' + mn + (md ? '（' + md + '）' : '');
  }
  let skillText;
  if (document.getElementById('skill-type').value === 'custom') {
    const rows = document.querySelectorAll('#custom-skills .custom-skill-row');
    const parts = [];
    rows.forEach(function (r) {
      const nm = (r.querySelector('.cs-name') ? r.querySelector('.cs-name').value : '').trim();
      if (!nm) return;
      const g = r.querySelector('.cs-grade') ? r.querySelector('.cs-grade').value : '';
      const ty = r.querySelector('.cs-type') ? r.querySelector('.cs-type').value : '';
      const pf = r.querySelector('.cs-prof') ? r.querySelector('.cs-prof').value : '皮毛';
      const ds = (r.querySelector('.cs-desc') ? r.querySelector('.cs-desc').value : '').trim();
      parts.push(开局武学文本(nm,g,ty,pf,ds));
    });
    skillText = parts.length ? '自得·' + parts.join('；') : '自得功法未填写';
  } else {
    const picked = [1, 2, 3].map(function (i) {
      const sk = document.getElementById('skill-' + i);
      const pf = document.getElementById('prof-' + i);
      if (!sk || !sk.value) return '';
      const p = pf ? pf.value : '';
      const parsed=/^(不入流|三品|二品|一品|后天|先天)([^《]*)《([^》]+)》/.exec(sk.value);
      return parsed?开局武学文本(parsed[3],parsed[1],parsed[2],p):sk.value+'（熟练度：'+(p||'皮毛')+'）';
    }).filter(Boolean);
    skillText = picked.length ? picked.join('、') : (d('skill') || '粗浅拳脚');
  }
  info.skill = info.level==='无修为'&&document.getElementById('skill-type').value!=='custom'?'尚未习武':skillText;
  const 百艺原始 = Array.prototype.slice.call(document.querySelectorAll('#art-rows .art-row')).map(function (r) {
    const a = r.querySelector('.art-name'), p = r.querySelector('.art-prof');
    return (a && a.value) ? { 名: a.value, 档: (p ? p.value : '一级 初窥门径') } : null;
  }).filter(Boolean);
  const 档序 = function (v) { return v.indexOf('三级') >= 0 ? 3 : v.indexOf('二级') >= 0 ? 2 : 1; };
  const 百艺表去重 = {};
  百艺原始.forEach(function (x) { if (!百艺表去重[x.名] || 档序(x.档) > 档序(百艺表去重[x.名].档)) 百艺表去重[x.名] = x; });
  const 百艺 = Object.keys(百艺表去重).map(function (k) { return k + '【' + 百艺表去重[k].档 + '】'; });
  info.arts = 百艺.length ? 百艺.join('、') : '未修百艺';

  const txt = `[OOC:
-开局预设: ${document.getElementById("preset").value || "自由创建"}
-初始档案: 玩家扮演${info.n} (${info.g})，年龄${info.age}，绰号【${info.nick}】。
-武道底蕴: 境界【${info.level}】，武学根基【${info.skill}】。
-百艺底蕴: ${info.arts}。
-身份背景: 隶属【${info.faction}】，当前身份【${info.job}】。背景来历: ${info.bg}
${info.level === '无修为' ? '-未入武道之因: ' + (info.whyNoRealm || '（未填写）') + '。' : ''}
-资产底蕴: 银两与外物【${info.money}】；兵器与灵物【${info.gear}】。
${info.party?'-起始同游: '+info.party:''}
${info.talents?'-天赋体质: '+info.talents:''}
-外貌特征: ${info.look}
-空间锚点: 大凉【${info.loc}】
-开场情景: ${info.scene}
请依以上角色设定演绎开场，变量记录遵循《变量更新规则》。
]`;
  return txt;
}

