      await triggerSlash(`/send ${txt.replace(/\n/g,' ')}`);
      for(let i=0;i<20&&!已发送();i++)await new Promise(r=>setTimeout(r,100));
      if(!已发送())throw Error('尚未确认档案已送达，请先检查聊天记录。');
      await triggerSlash('/trigger');
      if(b){b.textContent='已入局';b.disabled=true;}return;
    }
    if(typeof send_text_to_input==='function'){await send_text_to_input(txt,true);if(b){b.textContent='已填入，待发送';b.disabled=false;}return;}
    await navigator.clipboard.writeText(txt);if(b){b.textContent='已复制，待发送';b.disabled=false;}alert('卷宗已复制，请粘贴发送。');
  }catch(e){
    if(b){b.textContent=已发送()?'已发出，待续写':'再试入局';b.disabled=已发送();}
    alert(已发送()?'档案已发送，但续写未完成；请在聊天中重试生成。':'提交失败，可再次尝试：'+String(e.message||e));console.error(e);
  }finally{入局提交中=false;同步入局锁();}
}

/* __先天矫正：预设换好后统一矫正品级 —— 只有预设中标为「先天」的那几行显示并锁死为先天，其余行一律选不到先天 */
(function () {
  function 矫正() {
    var key = (document.getElementById('preset') || {}).value || '';
    var p = PRESETS[key] || {};
    var 串 = p.skill || '';
    var 先天名 = [];
    串.split('、').forEach(function (part) {
      var m = part.match(/^自得奇功·(三品|二品|一品|后天|先天)[^《]*《([^》]+)》/);
      if (m && m[1] === '先天') 先天名.push(m[2]);
    });
    var 串名 = 串.split('、').map(function (part) { var m = part.match(/《([^》]+)》/); return m ? m[1] : ''; });
    var 行 = document.querySelectorAll('.cs-grade');
    for (var i = 0; i < 行.length; i++) {
      var sel = 行[i], o = sel.querySelector('option.opt-xian');
      if (!o) continue;
      var 盒 = sel.parentElement, 名框 = 盒 ? 盒.querySelector('input, textarea') : null;
      var 名 = 名框 ? (名框.value || '').trim() : '';
      if (!名) 名 = 串名[i] || '';
      if (先天名.indexOf(名) >= 0) {
        o.disabled = false; o.removeAttribute('disabled');
        sel.value = '先天';
        o.disabled = true; o.setAttribute('disabled', '');   /* 显示为先天，但改不动 */
      } else {
        if (sel.value === '先天') sel.value = '三品';
        o.disabled = true; o.setAttribute('disabled', '');
      }
    }
  }
  window.__先天矫正 = 矫正;
  document.addEventListener('change', function (e) { if (e.target && e.target.id === 'preset') setTimeout(矫正, 30); }, true);
  document.addEventListener('click', function (e) { if (e.target && e.target.id === 'btn') setTimeout(矫正, 30); }, true);
  setTimeout(矫正, 60);
})();

/* ═══════════ [v3.2] 百艺去重：同一门只能选一次 ═══════════
   规则：任一行选定了某门百艺后，其余行的「百艺名称」下拉里该门变为 disabled；
   该行改选或删除后，即恢复可选。（熟练度下拉 .art-prof 不受影响。）
   实现方式：MutationObserver 监听 #art-rows 的行增删 + change 事件委托 ⇒ 不侵入原 addArtRow()。 */
(function () {
  function 刷新() {
    try {
      var box = document.getElementById("art-rows");
      if (!box) return;
    /* ★ v3.3 强制清重：若因"新增行默认选中第一项"导致多行同门，只保留第一行，其余置空 */
    (function(){
      try {
        var box2 = document.getElementById("art-rows");
        if (!box2) return;
        var 见 = {};
        Array.prototype.slice.call(box2.querySelectorAll("select.art-name")).forEach(function (s) {
          var v = s.value || "";
          if (!v) return;
          if (见[v]) { s.value = ""; }   /* 重复的置空 */
          else 见[v] = 1;
        });
      } catch (e) {}
    })();
      var sels = Array.prototype.slice.call(box.querySelectorAll("select.art-name"));
      var 已选 = {};
      sels.forEach(function (s) { if (s.value) 已选[s.value] = (已选[s.value] || 0) + 1; });
      sels.forEach(function (s) {
        Array.prototype.forEach.call(s.options, function (op) {
          if (!op.value) { op.disabled = false; return; }
          var 是自己 = (s.value === op.value);
          op.disabled = (!是自己 && 已选[op.value] >= 1);
        });
      });
    } catch (e) {}
  }
  window.刷新百艺去重 = 刷新;
  function 挂() {
    var box = document.getElementById("art-rows");
    if (!box) { setTimeout(挂, 300); return; }
    box.addEventListener("change", function (e) {
      var t = e.target;
      if (t && t.classList && t.classList.contains("art-name")) 刷新();
    }, true);
    try { new MutationObserver(刷新).observe(box, { childList: true, subtree: true }); } catch (e) {}
    /* 兜底：原删除按钮直接 remove() 时也能刷新 */

    刷新();
  }
   挂();
})();
</script>
</body>
</html>
