            var nm = name.match(/^[\u4e00-\u9fa5]+/);
            if (nm) name = nm[0];
            var icon = data['百艺图标'] || getIcon(name);
            var rank = data['造诣'] || '初窥门径';
            /* 净化境界：白名单匹配，只取合法境界值，丢弃AI混入的思维文本 */
            var rankList = ['初窥门径','登堂入室','融会贯通','登峰造极','技近乎道'];
            var rankFound = null;
            for (var ri = 0; ri < rankList.length; ri++) { if (rank.indexOf(rankList[ri]) >= 0) { rankFound = rankList[ri]; break; } }
            rank = rankFound || '初窥门径';
            var act = data['所作'] || '未见动作。';
            var quote = data['风评'] || '手段不俗。';
            var effect = data['见效'] || '未见成效。';

            /* 拆分点评：说话人 + 内容（格式 "说话人：内容"） */
            var speaker = '', quoteText = quote;
            var colonIdx = quote.indexOf('：');
            if (colonIdx === -1) colonIdx = quote.indexOf(':');
            if (colonIdx > 0) {
                speaker = quote.substring(0, colonIdx);
                quoteText = quote.substring(colonIdx + 1);
            }

            var html = `
