        ];

        function matchStage(stageText) {
            var s = stageText || '';
            for (var i = 0; i < STAGE_MAP.length; i++) {
                for (var k = 0; k < STAGE_MAP[i].keys.length; k++) {
                    if (s.indexOf(STAGE_MAP[i].keys[k]) >= 0) {
                        return STAGE_MAP[i];
                    }
                }
            }
            return null;
        }

        /* ========== 渲染 ========== */
        function renderPage(data,_el) {
            /* 上方栏目：由「突破阶段」查表固定，AI 不可改动 */
            var meta = matchStage(data['突破阶段']) || { name: '境界突破', icon: '☯️', level: '' };

            var name = meta.name;
