                    </div>

                    <div class="effect-box">
                        <span class="effect-label">突破效果</span>${effect}
                    </div>
                </div>
            `;
            _el.innerHTML = html;
        }

        /* ========== 主函数（延迟确保消息体同步） ========== */
        function init(_el) {
            setTimeout(function() {
                try {
                    var messageText = getMessageData();
                    if (!messageText) {
                        _el.innerHTML =
                            '<div class="breakthrough-container" style="padding:30px 16px;"><div class="loading">❌ 无法获取消息内容，请稍后再试</div></div>';
                        return;
                    }
                    var data = parseData(messageText);
                    renderPage(data, _el);
