            if (any) return result;

            var brackets = [];
            var bracketReg = /\[([^\]\n]+)\]/g;
            var bm;
            while ((bm = bracketReg.exec(scope)) !== null) {
                if (bm[1] && bm[1].trim()) brackets.push(bm[1].trim());
