/* No independent generation, timers or prompt injection. Reuse the memory source frame. */
function dlhPlotContext(frame,host){
 const ctx={...frame,userText:'',turnUserText:''},chat=host?.chat,sources=frame?.activeSources;
 delete ctx.previousPlot;delete ctx.previousPlotSourceKey;
 if(!Array.isArray(chat)||!Array.isArray(sources)||!sources.length)return {...ctx,trusted:false,activeSources:[],recentText:''};
 // A projection may end on a newly submitted user message and have no receipt
 // source yet. A committed frame must end exactly at its own source key.
 const end=frame.sourceKey?sources.findIndex(s=>s.key===frame.sourceKey):sources.length-1;
 if(end<0)return {...ctx,trusted:false,activeSources:[],recentText:''};
 const active=sources.slice(0,end+1),hash=DLH_PLOT_DISPATCH.hash;
 let prefix=hash(frame.chatId),previousId=-1;
 for(const source of active){
  const id=Number(source.messageId),row=chat[id],body=row?.mes??row?.message,swipe=String(row?.swipe_id||0);
  if(!Number.isInteger(id)||id<0||id<=previousId||body!==source.body||swipe!==String(source.swipeId))return {...ctx,trusted:false,activeSources:[],recentText:''};
  const started=row?.swipe_info?.[row?.swipe_id||0]?.gen_started??row?.gen_started;
  const slot=id+'/'+swipe+'/'+hash(prefix+'\n'+hash(body))+'/'+String(started??'');
  const generation=row?.extra?.dlh_memory_generation_v1?.[hash(slot)]||(started!=null&&started!==''?'host/'+String(started):'baseline/'+hash(slot));
  if(source.generationId!==generation||source.key!==id+'/'+swipe+'/'+generation)return {...ctx,trusted:false,activeSources:[],recentText:''};
  prefix=hash(prefix+'\n'+source.key+'\n'+hash(body));previousId=id;
 }
 const visible=typeof DLH_NARRATIVE_MEMORY!=='undefined'?DLH_NARRATIVE_MEMORY.visibleBody:DLH_PLOT_DISPATCH.visible;
 ctx.activeSources=active;ctx.stamp=prefix;ctx.recentText=active.slice(-3).map(s=>visible(s.body)).join('\n');
 for(let i=active.length-1;i>=0;i--){const source=active[i],row=chat[Number(source.messageId)];if(row.is_user&&!row.is_system){ctx.userText=visible(source.body);break;}}
 if(frame.sourceKey&&active.length>=2){
  const latest=active.at(-1),prior=active.at(-2),previous=chat[Number(prior.messageId)],reply=chat[Number(latest.messageId)];
  if(!reply.is_user&&!reply.is_system&&Number(prior.messageId)+1===Number(latest.messageId)&&previous.is_user&&!previous.is_system)ctx.turnUserText=visible(prior.body);
 }
 for(let i=frame.sourceKey?active.length-2:active.length-1;i>=0;i--){
  const source=active[i],row=chat[Number(source.messageId)],vars=Array.isArray(row?.variables)?row.variables[row.swipe_id||0]:row?.variables,plot=vars?.stat_data?.剧情线;
  if(plot){ctx.previousPlot=JSON.parse(JSON.stringify(plot));ctx.previousPlotSourceKey=source.key;break;}
 }
 return ctx;
}
function dlhCombinedNarrativeView(sd,host,bridge,catalog){const session=bridge.projection(sd,host),ctx=dlhPlotContext(session.context,host);return DLH_PLOT_DISPATCH.combined(sd,ctx,catalog,session.project);}
