rue,"public":true,"province":"南洋群岛","scope":"南洋群岛","rumors":[{"id":"芳闻-薇玛拉-1","ordinal":1,"text":"蒲甘城万塔的石阶前，白衣赤足的薇玛拉正坐在阴凉处，手里拿把小苇帚，帮看塔的老沙弥细细扫除佛龛石缝里的落叶，任凭香客来往也不抬头。","status":"approved"},{"id":"芳闻-薇玛拉-2","ordinal":2,"text":"蒲甘城门外的茶摊底下，那位长发散垂的白衣姑娘薇玛拉眼下正要了一碗清水歇脚，指尖正慢条斯理摩挲着颈上那串缺了木珠的旧链子。","status":"approved"},{"id":"芳闻-薇玛拉-3","ordinal":3,"text":"蒲甘城渡口边的水桥旁，薇玛拉正立在栈板上，替靠岸的采莲小童将一篓篓新鲜水白莲接上岸，整齐码在青石板边，引得过路行人都放慢了步子。","status":"approved"},{"id":"芳闻-薇玛拉-4","ordinal":4,"text":"蒲甘城外市集北头的药草棚前，持经人薇玛拉正驻足挑选驱热的苦草根，摊贩给她递过洗净的叶包，她正安静站在摊前等候称量。","status":"approved"}]},{"name":"阿玛雅","kind":"芳闻","publicName":"阿玛雅","enabled":true,"public":true,"province":"南洋群岛","scope":"南洋群岛","rumors":[{"id":"芳闻-阿玛雅-1","ordinal":1,"text":"巴石河口码头的石阶边，两臂刺满浪纹的阿玛雅正赤足踩在空鱼箱上，腰别两根藤木短棍，扯着嗓门替村里相熟的疍户跟收鱼贩子算账还价呢。","status":"approved"},{"id":"芳闻-阿玛雅-2","ordinal":2,"text":"素万城擂台旁的凉棚里，吕宋村邦的少头人阿玛雅正和几个南洋拳手拼桌，两根短棍横在桌角，她正拍着桌子同众人掷椰子壳赌酒，笑声极响亮。","status":"approved"},{"id":"芳闻-阿玛雅-3","ordinal":3,"text":"巴石河口大集市里的藤编摊前，短棍阿玛雅正叉着腰挑拣结实的藤皮绳，手里短棍上下晃悠着，跟铺子掌柜讨价还价，护短地替同村人多讨了两捆。","status":"approved"},{"id":"芳闻-阿玛雅-4","ordinal":4,"text":"蒲甘城南门外的河埠头边，阿玛雅正带着几个吕宋小伙蹲在栈桥上，手里拿短棍拨弄水里的浮木比试眼力，嘴里还在大声催促着船家快备缆绳。","status":"approved"}]},{"name":"巴月","kind":"芳闻","publicName":"巴月","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-巴月-1","ordinal":1,"text":"附近驿站的马料棚前，那位着短款豹皮装、手臂绘满青纹的巴月姑娘正拿胡萝卜喂驮马。她腰间盘着兽筋长鞭，正跟伙计仔细打听进深山打猎的路径呢。","status":"approved"},{"id":"芳闻-巴月-2","ordinal":2,"text":"街口铁匠铺子外，巴月正蹲在磨石旁试她长鞭上的铜环。她一身兽皮猎装引得不少人张望，她倒浑不在意，正挽着袖子催铁匠赶快给她的猎刀淬火。","status":"approved"},{"id":"芳闻-巴月-3","ordinal":3,"text":"听闻附近野味集市里热闹得很，巴月正扛着两头山鸡跟皮货掌柜讨价还价。她小腿上绘着山熊战纹，说话嗓门极脆，这会儿还在货摊前比划毛皮成色。","status":"approved"},{"id":"芳闻-巴月-4","ordinal":4,"text":"镇外老槐树下的茶摊边，巴月正踩着长凳喝大碗酽茶，随身的兽筋长鞭搭在桌角。邻桌的几个老猎户正跟她讨教鞣皮子的窍门，她聊得兴起，眼下还没打算动身。","status":"approved"}]},{"name":"蓝鸯","kind":"芳闻","publicName":"蓝鸯","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-蓝鸯-1","ordinal":1,"text":"镇子水井旁的凉棚下，叮叮当当一阵银饰脆响，原是蓝鸯姑娘正教几个孩童翻花绳。她腕上挂满精致小银铃，笑声清脆，这会儿正从兜里抓